// ---------------------------------------------------------------------------
// AUTO-GENERATED by Claude Code
// Purpose: inline chat for a CodeMirror editor, as Copilot's Ctrl+I: Shortcut.INLINE_EDIT (Alt+A; the AI also reads the chat so far)
//          opens a prompt box under the editor; Enter asks the backend (POST /inline_edit, inline_edit.py) to
//          rewrite the selection, else the whole text, and the answer is shown as a diff in the editor
//          (@codemirror/merge); while it thinks, light sweeps over the lines being rewritten. Tab accepts (one undo step), Esc discards, Enter again refines it.
// Usage: inlineEdit(() => ({ url, key, language, token, schema })) in an editor's extensions, built
//        once per editor (cell_editor.jsx, sql_editor.jsx); a falsy url leaves the editor without it.
// ---------------------------------------------------------------------------
import { Compartment, Prec, StateEffect, StateField } from "@codemirror/state";
import { Decoration, EditorView, keymap, showPanel } from "@codemirror/view";
import { isolateHistory, undo } from "@codemirror/commands";
import { unifiedMergeView } from "@codemirror/merge";

// The robot the bottom bar's Chat toggle shows (ui.py ICON_CHAT, a Nerd Font glyph): one icon
// for "the AI" everywhere.
const ICON_AI = "\u{F06A9}";

// the open box's controls, by editor, for the editor's own Tab / Esc
const boxes = new WeakMap();

const el = (tag, className, text) => {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text) node.textContent = text;
  return node;
};

/** Turn the editor's text into `next` as one undo step of its own, changing only the part that differs. */
const setText = (view, next, effects) => {
  const now = view.state.doc.toString();
  let start = 0;
  while (start < now.length && start < next.length && now[start] === next[start]) start++;
  let end = 0;
  while (end < now.length - start && end < next.length - start
    && now[now.length - 1 - end] === next[next.length - 1 - end]) end++;
  view.dispatch({
    changes: { from: start, to: now.length - end, insert: next.slice(start, next.length - end) },
    effects,
    annotations: isolateHistory.of("full"),
  });
};

export function inlineEdit(config) {
  // {from, to}: open on that range (the selection when the key was pressed); null: close
  const toggle = StateEffect.define();
  const diff = new Compartment();

  // {from, to}: the AI is rewriting those lines (they shimmer, app.css); null: it is done
  const thinking = StateEffect.define();
  const shimmerLine = Decoration.line({ class: "cm-inline-thinking-line" });
  const shimmer = StateField.define({
    create: () => Decoration.none,
    update(value, tr) {
      value = value.map(tr.changes);
      for (const effect of tr.effects) {
        if (!effect.is(thinking)) continue;
        if (!effect.value) return Decoration.none;
        const { doc } = tr.state;
        const first = doc.lineAt(Math.min(effect.value.from, doc.length)).number;
        const last = doc.lineAt(Math.min(effect.value.to, doc.length)).number;
        const lines = [];
        for (let n = first; n <= last; n++) lines.push(shimmerLine.range(doc.line(n).from));
        value = Decoration.set(lines);
      }
      return value;
    },
    provide: (field) => EditorView.decorations.from(field),
  });

  // the target, kept in step with edits made while the box is open
  const range = StateField.define({
    create: () => null,
    update(value, tr) {
      for (const effect of tr.effects) if (effect.is(toggle)) return effect.value;
      if (!value || !tr.docChanged) return value;
      return { ...value, from: tr.changes.mapPos(value.from, 1), to: tr.changes.mapPos(value.to, -1) };
    },
  });

  const box = (view) => {
    // set by the first answer: the text and target the proposal was made from, and the text showing it
    let base = null;
    let target = null;
    let proposal = null;
    let shown = null;
    let asked = 0; // a request id: a late answer to an older request (or a closed box) is dropped
    let closed = false;

    const selected = () => {
      const at = view.state.field(range);
      return at && at.from < at.to;
    };
    const dom = el("div", "cm-inline-edit");
    const input = el("input", "cm-inline-edit-input");
    input.placeholder = selected() ? "Change the selection…" : "Write or change this code…";
    input.spellcheck = false;
    const status = el("span", "cm-inline-edit-status", "Enter asks AI · Esc closes");
    const accept = el("button", "act", "Accept");
    const discard = el("button", "act", "Discard");
    accept.hidden = true;
    dom.append(el("span", "cm-inline-edit-icon", ICON_AI), input, status, accept, discard);

    /** Take the proposal back out: an undo when the text is still as proposed (so the undo history
     *  is as before), else a change back to the text it was made from. */
    const revert = (effects) => {
      // nothing to take out: no proposal yet, or one equal to the text it was made from (an undo
      // would then take back the user's own last edit)
      if (proposal === null || shown === base) return view.dispatch({ effects });
      if (view.state.doc.toString() === shown && undo(view)) return view.dispatch({ effects });
      return setText(view, base, effects);
    };

    const close = (keep) => {
      if (closed) return;
      closed = true;
      asked++;
      boxes.delete(view);
      const effects = [diff.reconfigure([]), toggle.of(null), thinking.of(null)];
      if (keep) view.dispatch({ effects });
      else revert(effects);
      view.focus();
    };

    const ask = async () => {
      const instruction = input.value.trim();
      if (!instruction) return;
      const id = ++asked;
      status.textContent = "Thinking…";
      status.classList.remove("is-error");
      dom.classList.add("is-thinking"); // the icon and status pulse (app.css)
      // the first ask fixes what is being changed; refining asks again about the same text
      const code = proposal === null ? view.state.doc.toString() : base;
      // nothing selected: the whole text is the target (the answer replaces it, not "insert at the cursor")
      const picked = view.state.field(range);
      const whole = { from: 0, to: code.length, all: true };
      const at = proposal !== null ? target : picked.from < picked.to ? picked : whole;
      view.dispatch({ effects: thinking.of(at) });
      const { url, language, token, schema } = config();
      let answer;
      try {
        const response = await fetch(url, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          // three pieces of text, not offsets: JS counts UTF-16 units, Python code points
          // `selected` is "" when the target is the whole text (then it is all in `before`)
          body: JSON.stringify({ language, token, schema, instruction, previous: proposal,
            before: at.all ? code : code.slice(0, at.from),
            selected: at.all ? "" : code.slice(at.from, at.to),
            after: at.all ? "" : code.slice(at.to) }),
        });
        answer = response.ok ? await response.json() : { error: `${response.status} ${response.statusText}` };
      } catch (error) {
        answer = { error: `backend unreachable (${error.message})` };
      }
      // the chat title's meter adds this call's cost (State.refresh_usage), even when the box was closed
      document.querySelector("[data-usage-refresh]")?.click();
      if (closed || id !== asked) return;
      dom.classList.remove("is-thinking");
      // what the call used (session.TurnUsage.summary), also on a failure
      const used = answer.usage ? ` · ${answer.usage}` : "";
      view.dispatch({ effects: thinking.of(null) });
      if (answer.error) {
        status.textContent = answer.error + used;
        status.classList.add("is-error");
        return;
      }
      if (proposal !== null) revert([]); // one proposal at a time: the last one goes first
      [base, target, proposal] = [code, at, answer.code];
      shown = code.slice(0, at.from) + proposal + code.slice(at.to);
      setText(view, shown, diff.reconfigure(unifiedMergeView({ original: base, mergeControls: false })));
      status.textContent = `Tab accepts · Esc discards · Enter refines${used}`;
      status.title = "This call: cost · input tokens · output tokens · model requests (details in the debug log)";
      accept.hidden = false;
    };

    const controls = { accept: () => close(true), discard: () => close(false), focus: () => input.focus(),
      pending: () => proposal !== null };
    boxes.set(view, controls);
    accept.addEventListener("click", controls.accept);
    discard.addEventListener("click", controls.discard);
    input.addEventListener("keydown", (event) => {
      const handled = { Enter: ask, Escape: controls.discard, Tab: proposal !== null ? controls.accept : null }[event.key];
      if (!handled) return;
      // stop it here: the page's Esc (panes.js) would also close a floating view
      event.preventDefault();
      event.stopPropagation();
      handled();
    });
    return {
      dom,
      top: false,
      mount: () => input.focus(),
      // the editor dropped the box itself (eg its extensions were rebuilt): forget it
      destroy: () => {
        closed = true;
        if (boxes.get(view) === controls) boxes.delete(view);
      },
    };
  };

  const start = (view) => {
    if (!config().url) return false;
    const current = boxes.get(view);
    if (current) {
      current.focus();
      return true;
    }
    const { from, to } = view.state.selection.main;
    view.dispatch({ effects: toggle.of({ from, to }) });
    return true;
  };

  return [
    range,
    shimmer,
    // `box` itself is the panel: the same function while open, so edits don't rebuild the box
    showPanel.from(range, (value) => (value ? box : null)),
    diff.of([]),
    Prec.highest(keymap.of([
      { key: config().key || "Alt-a", run: start },
    ])),
    // Tab / Esc in the editor while the box is open: accept a proposal / close
    Prec.highest(EditorView.domEventHandlers({
      keydown(event, view) {
        const current = boxes.get(view);
        if (!current) return false;
        const action = event.key === "Escape" ? current.discard : event.key === "Tab" && current.pending() ? current.accept : null;
        if (!action) return false;
        event.preventDefault();
        event.stopPropagation();
        action();
        return true;
      },
    })),
  ];
}
